/* DXGI_PRESENT_PARAMETERS (struct) */

static inline size_t
npt_sizeof_DXGI_PRESENT_PARAMETERS(const DXGI_PRESENT_PARAMETERS *val, int max_mode)
{
    size_t size = 0;
    size += npt_sizeof_UINT(&val->DirtyRectsCount, max_mode);
    size += npt_sizeof_array_count(val->pDirtyRects ? val->DirtyRectsCount : 0);
    for (uint32_t _i = 0; _i < (val->pDirtyRects ? val->DirtyRectsCount : 0); _i++)
        size += npt_sizeof_RECT(&val->pDirtyRects[_i], max_mode);
    size += npt_sizeof_simple_pointer(val->pScrollRect);
    if (val->pScrollRect)
        size += npt_sizeof_RECT(val->pScrollRect, max_mode);
    size += npt_sizeof_simple_pointer(val->pScrollOffset);
    if (val->pScrollOffset)
        size += npt_sizeof_POINT(val->pScrollOffset, max_mode);
    return size;
}

static inline void
npt_encode_DXGI_PRESENT_PARAMETERS(struct npt_cs_encoder *enc, const DXGI_PRESENT_PARAMETERS *val)
{
    npt_encode_UINT(enc, &val->DirtyRectsCount);
    if (val->pDirtyRects) {
        npt_encode_array_count(enc, npt_counted_pointer_wire_count(val->pDirtyRects, (uint64_t)(val->DirtyRectsCount)));
        for (uint32_t _i = 0; _i < (uint32_t)(val->DirtyRectsCount); _i++)
            npt_encode_RECT(enc, &val->pDirtyRects[_i]);
    } else {
        npt_encode_array_count(enc, 0);
    }
    if (npt_encode_simple_pointer(enc, val->pScrollRect))
        npt_encode_RECT(enc, val->pScrollRect);
    if (npt_encode_simple_pointer(enc, val->pScrollOffset))
        npt_encode_POINT(enc, val->pScrollOffset);
}

