static inline size_t
npt_sizeof_D3D11_VIDEO_DECODER_BUFFER_DESC2(const D3D11_VIDEO_DECODER_BUFFER_DESC2 *val, int max_mode)
{
    size_t size = 0;
    size += npt_sizeof_D3D11_VIDEO_DECODER_BUFFER_TYPE(&val->BufferType, max_mode);
    size += npt_sizeof_UINT(&val->DataOffset, max_mode);
    size += npt_sizeof_UINT(&val->DataSize, max_mode);
    if (val->pIV) {
        size += npt_sizeof_array_count(val->IVSize);
        size += npt_sizeof_blob_array(val->pIV, val->IVSize);
    } else {
        size += npt_sizeof_array_count(0);
    }
    size += npt_sizeof_UINT(&val->IVSize, max_mode);
    size += npt_sizeof_array_count(val->pSubSampleMappingBlock ? val->SubSampleMappingCount : 0);
    for (uint32_t _i = 0; _i < (val->pSubSampleMappingBlock ? val->SubSampleMappingCount : 0); _i++)
        size += npt_sizeof_D3D11_VIDEO_DECODER_SUB_SAMPLE_MAPPING_BLOCK(&val->pSubSampleMappingBlock[_i], max_mode);
    size += npt_sizeof_UINT(&val->SubSampleMappingCount, max_mode);
    size += npt_sizeof_UINT(&val->cBlocksStripeEncrypted, max_mode);
    size += npt_sizeof_UINT(&val->cBlocksStripeClear, max_mode);
    return size;
}

static inline void
npt_encode_D3D11_VIDEO_DECODER_BUFFER_DESC2(struct npt_cs_encoder *enc, const D3D11_VIDEO_DECODER_BUFFER_DESC2 *val)
{
    npt_encode_D3D11_VIDEO_DECODER_BUFFER_TYPE(enc, &val->BufferType);
    npt_encode_UINT(enc, &val->DataOffset);
    npt_encode_UINT(enc, &val->DataSize);
    if (val->pIV) {
        npt_encode_array_count(enc, val->IVSize);
        npt_encode_blob_array(enc, val->pIV, val->IVSize);
    } else {
        npt_encode_array_count(enc, 0);
    }
    npt_encode_UINT(enc, &val->IVSize);
    if (val->pSubSampleMappingBlock) {
        npt_encode_array_count(enc, npt_counted_pointer_wire_count(val->pSubSampleMappingBlock, (uint64_t)(val->SubSampleMappingCount)));
        for (uint32_t _i = 0; _i < (uint32_t)(val->SubSampleMappingCount); _i++)
            npt_encode_D3D11_VIDEO_DECODER_SUB_SAMPLE_MAPPING_BLOCK(enc, &val->pSubSampleMappingBlock[_i]);
    } else {
        npt_encode_array_count(enc, 0);
    }
    npt_encode_UINT(enc, &val->SubSampleMappingCount);
    npt_encode_UINT(enc, &val->cBlocksStripeEncrypted);
    npt_encode_UINT(enc, &val->cBlocksStripeClear);
}

static inline void
npt_decode_D3D11_VIDEO_DECODER_BUFFER_DESC2(struct npt_cs_decoder *dec, D3D11_VIDEO_DECODER_BUFFER_DESC2 *val)
{
    npt_decode_D3D11_VIDEO_DECODER_BUFFER_TYPE(dec, &val->BufferType);
    npt_decode_UINT(dec, &val->DataOffset);
    npt_decode_UINT(dec, &val->DataSize);
    {
        const uint64_t _blob_size = npt_decode_array_count_unchecked(dec);
        if (_blob_size) {
            val->pIV = npt_cs_decoder_alloc_temp(dec, _blob_size);
            if (!val->pIV) return;
            npt_decode_blob_array(dec, (void *)val->pIV, _blob_size);
        } else {
            val->pIV = NULL;
        }
    }
    npt_decode_UINT(dec, &val->IVSize);
    {
        uint64_t _count = 0;
        if (npt_decode_counted_pointer_count(dec, &_count)) {
            val->pSubSampleMappingBlock = npt_cs_decoder_alloc_temp_array(dec, sizeof(D3D11_VIDEO_DECODER_SUB_SAMPLE_MAPPING_BLOCK), _count ? _count : 1);
            if (!val->pSubSampleMappingBlock) return;
            for (uint32_t _i = 0; _i < (uint32_t)_count; _i++)
                npt_decode_D3D11_VIDEO_DECODER_SUB_SAMPLE_MAPPING_BLOCK(dec, (D3D11_VIDEO_DECODER_SUB_SAMPLE_MAPPING_BLOCK *)&val->pSubSampleMappingBlock[_i]);
        } else {
            (void)(val->SubSampleMappingCount); /* unused: count_expr from registry */
            val->pSubSampleMappingBlock = NULL;
        }
    }
    npt_decode_UINT(dec, &val->SubSampleMappingCount);
    npt_decode_UINT(dec, &val->cBlocksStripeEncrypted);
    npt_decode_UINT(dec, &val->cBlocksStripeClear);
}

