/* D3D12_CLEAR_VALUE (struct) */

static inline size_t
npt_sizeof_D3D12_CLEAR_VALUE(const D3D12_CLEAR_VALUE *val, int max_mode)
{
    size_t size = 0;
    size += npt_sizeof_DXGI_FORMAT(&val->Format, max_mode);
    if (max_mode) {
        size_t _arm_max = 0;
        { size_t _arm = 0;
            _arm += npt_sizeof_array_count(4);
            _arm += npt_sizeof_FLOAT_array((const FLOAT *)val->Color, 4);
            if (_arm > _arm_max) _arm_max = _arm; }
        { size_t _arm = 0;
            _arm += npt_sizeof_D3D12_DEPTH_STENCIL_VALUE(&val->DepthStencil, max_mode);
            if (_arm > _arm_max) _arm_max = _arm; }
        size += _arm_max;
    } else {
        if (!(val->Format == DXGI_FORMAT_D16_UNORM || val->Format == DXGI_FORMAT_D24_UNORM_S8_UINT || val->Format == DXGI_FORMAT_D32_FLOAT || val->Format == DXGI_FORMAT_D32_FLOAT_S8X24_UINT)) {
        size += npt_sizeof_array_count(4);
        size += npt_sizeof_FLOAT_array((const FLOAT *)val->Color, 4);
        }
        if (val->Format == DXGI_FORMAT_D16_UNORM || val->Format == DXGI_FORMAT_D24_UNORM_S8_UINT || val->Format == DXGI_FORMAT_D32_FLOAT || val->Format == DXGI_FORMAT_D32_FLOAT_S8X24_UINT) {
        size += npt_sizeof_D3D12_DEPTH_STENCIL_VALUE(&val->DepthStencil, max_mode);
        }
    }
    return size;
}

static inline void
npt_encode_D3D12_CLEAR_VALUE(struct npt_cs_encoder *enc, const D3D12_CLEAR_VALUE *val)
{
    npt_encode_DXGI_FORMAT(enc, &val->Format);
    if (!(val->Format == DXGI_FORMAT_D16_UNORM || val->Format == DXGI_FORMAT_D24_UNORM_S8_UINT || val->Format == DXGI_FORMAT_D32_FLOAT || val->Format == DXGI_FORMAT_D32_FLOAT_S8X24_UINT)) {
    npt_encode_array_count(enc, 4);
    npt_encode_FLOAT_array(enc, (const FLOAT *)val->Color, 4);
    }
    if (val->Format == DXGI_FORMAT_D16_UNORM || val->Format == DXGI_FORMAT_D24_UNORM_S8_UINT || val->Format == DXGI_FORMAT_D32_FLOAT || val->Format == DXGI_FORMAT_D32_FLOAT_S8X24_UINT) {
    npt_encode_D3D12_DEPTH_STENCIL_VALUE(enc, &val->DepthStencil);
    }
}

static inline void
npt_decode_D3D12_CLEAR_VALUE(struct npt_cs_decoder *dec, D3D12_CLEAR_VALUE *val)
{
    npt_decode_DXGI_FORMAT(dec, &val->Format);
    if (!(val->Format == DXGI_FORMAT_D16_UNORM || val->Format == DXGI_FORMAT_D24_UNORM_S8_UINT || val->Format == DXGI_FORMAT_D32_FLOAT || val->Format == DXGI_FORMAT_D32_FLOAT_S8X24_UINT)) {
    (void)npt_decode_array_count(dec, 4);
    npt_decode_FLOAT_array(dec, (FLOAT *)val->Color, 4);
    }
    if (val->Format == DXGI_FORMAT_D16_UNORM || val->Format == DXGI_FORMAT_D24_UNORM_S8_UINT || val->Format == DXGI_FORMAT_D32_FLOAT || val->Format == DXGI_FORMAT_D32_FLOAT_S8X24_UINT) {
    npt_decode_D3D12_DEPTH_STENCIL_VALUE(dec, &val->DepthStencil);
    }
}

