/* D3D12_STATE_OBJECT_DESC (struct) */

static inline size_t
npt_sizeof_D3D12_STATE_OBJECT_DESC(const D3D12_STATE_OBJECT_DESC *val, int max_mode)
{
    size_t size = 0;
    size += npt_sizeof_D3D12_STATE_OBJECT_TYPE(&val->Type, max_mode);
    size += npt_sizeof_UINT(&val->NumSubobjects, max_mode);
    size += npt_sizeof_array_count(val->pSubobjects ? val->NumSubobjects : 0);
    for (uint32_t _i = 0; _i < (val->pSubobjects ? val->NumSubobjects : 0); _i++)
        size += npt_sizeof_D3D12_STATE_SUBOBJECT(&val->pSubobjects[_i], max_mode);
    return size;
}

static inline void
npt_encode_D3D12_STATE_OBJECT_DESC(struct npt_cs_encoder *enc, const D3D12_STATE_OBJECT_DESC *val)
{
    npt_encode_D3D12_STATE_OBJECT_TYPE(enc, &val->Type);
    npt_encode_UINT(enc, &val->NumSubobjects);
    if (val->pSubobjects) {
        npt_encode_array_count(enc, npt_counted_pointer_wire_count(val->pSubobjects, (uint64_t)(val->NumSubobjects)));
        for (uint32_t _i = 0; _i < (uint32_t)(val->NumSubobjects); _i++)
            npt_encode_D3D12_STATE_SUBOBJECT(enc, &val->pSubobjects[_i]);
    } else {
        npt_encode_array_count(enc, 0);
    }
}

static inline void
npt_decode_D3D12_STATE_OBJECT_DESC(struct npt_cs_decoder *dec, D3D12_STATE_OBJECT_DESC *val)
{
    npt_decode_D3D12_STATE_OBJECT_TYPE(dec, &val->Type);
    npt_decode_UINT(dec, &val->NumSubobjects);
    {
        uint64_t _count = 0;
        if (npt_decode_counted_pointer_count(dec, &_count)) {
            val->pSubobjects = npt_cs_decoder_alloc_temp_array(dec, sizeof(D3D12_STATE_SUBOBJECT), _count ? _count : 1);
            if (!val->pSubobjects) return;
            for (uint32_t _i = 0; _i < (uint32_t)_count; _i++)
                npt_decode_D3D12_STATE_SUBOBJECT(dec, (D3D12_STATE_SUBOBJECT *)&val->pSubobjects[_i]);
        } else {
            (void)(val->NumSubobjects); /* unused: count_expr from registry */
            val->pSubobjects = NULL;
        }
    }
}

static inline void
npt_replace_D3D12_STATE_OBJECT_DESC_handle(struct npt_dispatch_context *ctx, D3D12_STATE_OBJECT_DESC *val)
{
    if (val->pSubobjects) {
        for (uint32_t _i = 0; _i < (uint32_t)(val->NumSubobjects); _i++)
            npt_replace_D3D12_STATE_SUBOBJECT_handle(ctx, &((D3D12_STATE_SUBOBJECT *)val->pSubobjects)[_i]);
    }
}

