/* D3D12_SET_PROGRAM_DESC (struct) */

static inline size_t
npt_sizeof_D3D12_SET_PROGRAM_DESC(const D3D12_SET_PROGRAM_DESC *val, int max_mode)
{
    size_t size = 0;
    size += npt_sizeof_D3D12_PROGRAM_TYPE(&val->Type, max_mode);
    if (max_mode) {
        size_t _arm_max = 0;
        { size_t _arm = 0;
            _arm += npt_sizeof_D3D12_SET_GENERIC_PIPELINE_DESC(&val->GenericPipeline, max_mode);
            if (_arm > _arm_max) _arm_max = _arm; }
        { size_t _arm = 0;
            _arm += npt_sizeof_D3D12_SET_RAYTRACING_PIPELINE_DESC(&val->RaytracingPipeline, max_mode);
            if (_arm > _arm_max) _arm_max = _arm; }
        { size_t _arm = 0;
            _arm += npt_sizeof_D3D12_SET_WORK_GRAPH_DESC(&val->WorkGraph, max_mode);
            if (_arm > _arm_max) _arm_max = _arm; }
        size += _arm_max;
    } else {
        if (val->Type == D3D12_PROGRAM_TYPE_GENERIC_PIPELINE) {
        size += npt_sizeof_D3D12_SET_GENERIC_PIPELINE_DESC(&val->GenericPipeline, max_mode);
        }
        if (val->Type == D3D12_PROGRAM_TYPE_RAYTRACING_PIPELINE) {
        size += npt_sizeof_D3D12_SET_RAYTRACING_PIPELINE_DESC(&val->RaytracingPipeline, max_mode);
        }
        if (val->Type == D3D12_PROGRAM_TYPE_WORK_GRAPH) {
        size += npt_sizeof_D3D12_SET_WORK_GRAPH_DESC(&val->WorkGraph, max_mode);
        }
    }
    return size;
}

static inline void
npt_encode_D3D12_SET_PROGRAM_DESC(struct npt_cs_encoder *enc, const D3D12_SET_PROGRAM_DESC *val)
{
    npt_encode_D3D12_PROGRAM_TYPE(enc, &val->Type);
    if (val->Type == D3D12_PROGRAM_TYPE_GENERIC_PIPELINE) {
    npt_encode_D3D12_SET_GENERIC_PIPELINE_DESC(enc, &val->GenericPipeline);
    }
    if (val->Type == D3D12_PROGRAM_TYPE_RAYTRACING_PIPELINE) {
    npt_encode_D3D12_SET_RAYTRACING_PIPELINE_DESC(enc, &val->RaytracingPipeline);
    }
    if (val->Type == D3D12_PROGRAM_TYPE_WORK_GRAPH) {
    npt_encode_D3D12_SET_WORK_GRAPH_DESC(enc, &val->WorkGraph);
    }
}

static inline void
npt_decode_D3D12_SET_PROGRAM_DESC(struct npt_cs_decoder *dec, D3D12_SET_PROGRAM_DESC *val)
{
    npt_decode_D3D12_PROGRAM_TYPE(dec, &val->Type);
    if (val->Type == D3D12_PROGRAM_TYPE_GENERIC_PIPELINE) {
    npt_decode_D3D12_SET_GENERIC_PIPELINE_DESC(dec, &val->GenericPipeline);
    }
    if (val->Type == D3D12_PROGRAM_TYPE_RAYTRACING_PIPELINE) {
    npt_decode_D3D12_SET_RAYTRACING_PIPELINE_DESC(dec, &val->RaytracingPipeline);
    }
    if (val->Type == D3D12_PROGRAM_TYPE_WORK_GRAPH) {
    npt_decode_D3D12_SET_WORK_GRAPH_DESC(dec, &val->WorkGraph);
    }
}

/* D3D12_NODE_CPU_INPUT (struct) */

static inline size_t
npt_sizeof_D3D12_NODE_CPU_INPUT(const D3D12_NODE_CPU_INPUT *val, int max_mode)
{
    size_t size = 0;
    size += npt_sizeof_UINT(&val->EntrypointIndex, max_mode);
    size += npt_sizeof_UINT(&val->NumRecords, max_mode);
    if (val->pRecords) {
        size += npt_sizeof_array_count(val->NumRecords * val->RecordStrideInBytes);
        size += npt_sizeof_blob_array(val->pRecords, val->NumRecords * val->RecordStrideInBytes);
    } else {
        size += npt_sizeof_array_count(0);
    }
    size += npt_sizeof_UINT64(&val->RecordStrideInBytes, max_mode);
    return size;
}

static inline void
npt_encode_D3D12_NODE_CPU_INPUT(struct npt_cs_encoder *enc, const D3D12_NODE_CPU_INPUT *val)
{
    npt_encode_UINT(enc, &val->EntrypointIndex);
    npt_encode_UINT(enc, &val->NumRecords);
    if (val->pRecords) {
        npt_encode_array_count(enc, val->NumRecords * val->RecordStrideInBytes);
        npt_encode_blob_array(enc, val->pRecords, val->NumRecords * val->RecordStrideInBytes);
    } else {
        npt_encode_array_count(enc, 0);
    }
    npt_encode_UINT64(enc, &val->RecordStrideInBytes);
}

static inline void
npt_decode_D3D12_NODE_CPU_INPUT(struct npt_cs_decoder *dec, D3D12_NODE_CPU_INPUT *val)
{
    npt_decode_UINT(dec, &val->EntrypointIndex);
    npt_decode_UINT(dec, &val->NumRecords);
    {
        const uint64_t _blob_size = npt_decode_array_count_unchecked(dec);
        if (_blob_size) {
            val->pRecords = npt_cs_decoder_alloc_temp(dec, _blob_size);
            if (!val->pRecords) return;
            npt_decode_blob_array(dec, (void *)val->pRecords, _blob_size);
        } else {
            val->pRecords = NULL;
        }
    }
    npt_decode_UINT64(dec, &val->RecordStrideInBytes);
}

