/* D3D12_BARRIER_GROUP (struct) */

static inline size_t
npt_sizeof_D3D12_BARRIER_GROUP(const D3D12_BARRIER_GROUP *val, int max_mode)
{
    size_t size = 0;
    size += npt_sizeof_D3D12_BARRIER_TYPE(&val->Type, max_mode);
    size += npt_sizeof_UINT32(&val->NumBarriers, max_mode);
    if (max_mode) {
        size_t _arm_max = 0;
        { size_t _arm = 0;
            _arm += npt_sizeof_array_count(val->pGlobalBarriers ? val->NumBarriers : 0);
            for (uint32_t _i = 0; _i < (val->pGlobalBarriers ? val->NumBarriers : 0); _i++)
                _arm += npt_sizeof_D3D12_GLOBAL_BARRIER(&val->pGlobalBarriers[_i], max_mode);
            if (_arm > _arm_max) _arm_max = _arm; }
        { size_t _arm = 0;
            _arm += npt_sizeof_array_count(val->pTextureBarriers ? val->NumBarriers : 0);
            for (uint32_t _i = 0; _i < (val->pTextureBarriers ? val->NumBarriers : 0); _i++)
                _arm += npt_sizeof_D3D12_TEXTURE_BARRIER(&val->pTextureBarriers[_i], max_mode);
            if (_arm > _arm_max) _arm_max = _arm; }
        { size_t _arm = 0;
            _arm += npt_sizeof_array_count(val->pBufferBarriers ? val->NumBarriers : 0);
            for (uint32_t _i = 0; _i < (val->pBufferBarriers ? val->NumBarriers : 0); _i++)
                _arm += npt_sizeof_D3D12_BUFFER_BARRIER(&val->pBufferBarriers[_i], max_mode);
            if (_arm > _arm_max) _arm_max = _arm; }
        size += _arm_max;
    } else {
        if (val->Type == D3D12_BARRIER_TYPE_GLOBAL) {
        size += npt_sizeof_array_count(val->pGlobalBarriers ? val->NumBarriers : 0);
        for (uint32_t _i = 0; _i < (val->pGlobalBarriers ? val->NumBarriers : 0); _i++)
            size += npt_sizeof_D3D12_GLOBAL_BARRIER(&val->pGlobalBarriers[_i], max_mode);
        }
        if (val->Type == D3D12_BARRIER_TYPE_TEXTURE) {
        size += npt_sizeof_array_count(val->pTextureBarriers ? val->NumBarriers : 0);
        for (uint32_t _i = 0; _i < (val->pTextureBarriers ? val->NumBarriers : 0); _i++)
            size += npt_sizeof_D3D12_TEXTURE_BARRIER(&val->pTextureBarriers[_i], max_mode);
        }
        if (val->Type == D3D12_BARRIER_TYPE_BUFFER) {
        size += npt_sizeof_array_count(val->pBufferBarriers ? val->NumBarriers : 0);
        for (uint32_t _i = 0; _i < (val->pBufferBarriers ? val->NumBarriers : 0); _i++)
            size += npt_sizeof_D3D12_BUFFER_BARRIER(&val->pBufferBarriers[_i], max_mode);
        }
    }
    return size;
}

static inline void
npt_encode_D3D12_BARRIER_GROUP(struct npt_cs_encoder *enc, const D3D12_BARRIER_GROUP *val)
{
    npt_encode_D3D12_BARRIER_TYPE(enc, &val->Type);
    npt_encode_UINT32(enc, &val->NumBarriers);
    if (val->Type == D3D12_BARRIER_TYPE_GLOBAL) {
    if (val->pGlobalBarriers) {
        npt_encode_array_count(enc, npt_counted_pointer_wire_count(val->pGlobalBarriers, (uint64_t)(val->NumBarriers)));
        for (uint32_t _i = 0; _i < (uint32_t)(val->NumBarriers); _i++)
            npt_encode_D3D12_GLOBAL_BARRIER(enc, &val->pGlobalBarriers[_i]);
    } else {
        npt_encode_array_count(enc, 0);
    }
    }
    if (val->Type == D3D12_BARRIER_TYPE_TEXTURE) {
    if (val->pTextureBarriers) {
        npt_encode_array_count(enc, npt_counted_pointer_wire_count(val->pTextureBarriers, (uint64_t)(val->NumBarriers)));
        for (uint32_t _i = 0; _i < (uint32_t)(val->NumBarriers); _i++)
            npt_encode_D3D12_TEXTURE_BARRIER(enc, &val->pTextureBarriers[_i]);
    } else {
        npt_encode_array_count(enc, 0);
    }
    }
    if (val->Type == D3D12_BARRIER_TYPE_BUFFER) {
    if (val->pBufferBarriers) {
        npt_encode_array_count(enc, npt_counted_pointer_wire_count(val->pBufferBarriers, (uint64_t)(val->NumBarriers)));
        for (uint32_t _i = 0; _i < (uint32_t)(val->NumBarriers); _i++)
            npt_encode_D3D12_BUFFER_BARRIER(enc, &val->pBufferBarriers[_i]);
    } else {
        npt_encode_array_count(enc, 0);
    }
    }
}

static inline void
npt_decode_D3D12_BARRIER_GROUP(struct npt_cs_decoder *dec, D3D12_BARRIER_GROUP *val)
{
    npt_decode_D3D12_BARRIER_TYPE(dec, &val->Type);
    npt_decode_UINT32(dec, &val->NumBarriers);
    if (val->Type == D3D12_BARRIER_TYPE_GLOBAL) {
    {
        uint64_t _count = 0;
        if (npt_decode_counted_pointer_count(dec, &_count)) {
            val->pGlobalBarriers = npt_cs_decoder_alloc_temp_array(dec, sizeof(D3D12_GLOBAL_BARRIER), _count ? _count : 1);
            if (!val->pGlobalBarriers) return;
            for (uint32_t _i = 0; _i < (uint32_t)_count; _i++)
                npt_decode_D3D12_GLOBAL_BARRIER(dec, (D3D12_GLOBAL_BARRIER *)&val->pGlobalBarriers[_i]);
        } else {
            (void)(val->NumBarriers); /* unused: count_expr from registry */
            val->pGlobalBarriers = NULL;
        }
    }
    }
    if (val->Type == D3D12_BARRIER_TYPE_TEXTURE) {
    {
        uint64_t _count = 0;
        if (npt_decode_counted_pointer_count(dec, &_count)) {
            val->pTextureBarriers = npt_cs_decoder_alloc_temp_array(dec, sizeof(D3D12_TEXTURE_BARRIER), _count ? _count : 1);
            if (!val->pTextureBarriers) return;
            for (uint32_t _i = 0; _i < (uint32_t)_count; _i++)
                npt_decode_D3D12_TEXTURE_BARRIER(dec, (D3D12_TEXTURE_BARRIER *)&val->pTextureBarriers[_i]);
        } else {
            (void)(val->NumBarriers); /* unused: count_expr from registry */
            val->pTextureBarriers = NULL;
        }
    }
    }
    if (val->Type == D3D12_BARRIER_TYPE_BUFFER) {
    {
        uint64_t _count = 0;
        if (npt_decode_counted_pointer_count(dec, &_count)) {
            val->pBufferBarriers = npt_cs_decoder_alloc_temp_array(dec, sizeof(D3D12_BUFFER_BARRIER), _count ? _count : 1);
            if (!val->pBufferBarriers) return;
            for (uint32_t _i = 0; _i < (uint32_t)_count; _i++)
                npt_decode_D3D12_BUFFER_BARRIER(dec, (D3D12_BUFFER_BARRIER *)&val->pBufferBarriers[_i]);
        } else {
            (void)(val->NumBarriers); /* unused: count_expr from registry */
            val->pBufferBarriers = NULL;
        }
    }
    }
}

static inline void
npt_replace_D3D12_BARRIER_GROUP_handle(struct npt_dispatch_context *ctx, D3D12_BARRIER_GROUP *val)
{
    if (val->Type == D3D12_BARRIER_TYPE_TEXTURE) {
    if (val->pTextureBarriers) {
        for (uint32_t _i = 0; _i < (uint32_t)(val->NumBarriers); _i++)
            npt_replace_D3D12_TEXTURE_BARRIER_handle(ctx, &((D3D12_TEXTURE_BARRIER *)val->pTextureBarriers)[_i]);
    }
    }
    if (val->Type == D3D12_BARRIER_TYPE_BUFFER) {
    if (val->pBufferBarriers) {
        for (uint32_t _i = 0; _i < (uint32_t)(val->NumBarriers); _i++)
            npt_replace_D3D12_BUFFER_BARRIER_handle(ctx, &((D3D12_BUFFER_BARRIER *)val->pBufferBarriers)[_i]);
    }
    }
}

